from __future__ import annotations

from minidb.types import (
    COMPARISON_OPS,
    And,
    ColumnDef,
    ColumnRef,
    ColumnType,
    Comparison,
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    Expr,
    InsertStmt,
    IsNull,
    Literal,
    Not,
    Or,
    SelectStmt,
    SQLSyntaxError,
    Statement,
    Token,
    TokenType,
    Value,
)

__all__ = ["parse", "parse_script", "parse_expression"]


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    def consume(token_type: TokenType):
        if tokens and tokens[0].type == token_type:
            return tokens.pop(0)
        raise SQLSyntaxError(f"Expected {token_type.value}")

    def parse_create_table():
        consume(TokenType.KEYWORD)  # CREATE
        consume(TokenType.KEYWORD)  # TABLE
        table_name = consume(TokenType.IDENTIFIER).value
        consume(TokenType.OPERATOR)  # (
        columns = []
        while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
            col_name = consume(TokenType.IDENTIFIER).value
            consume(TokenType.KEYWORD)  # TYPE
            col_type_str = consume(TokenType.KEYWORD).value
            if col_type_str == "INTEGER":
                col_type = ColumnType.INTEGER
            elif col_type_str == "TEXT":
                col_type = ColumnType.TEXT
            elif col_type_str == "BOOLEAN":
                col_type = ColumnType.BOOLEAN
            else:
                raise SQLSyntaxError(f"Invalid column type: {col_type_str}")
            columns.append(ColumnDef(col_name, col_type))
            if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                consume(TokenType.OPERATOR)  # ,
        consume(TokenType.OPERATOR)  # )
        return CreateTableStmt(table_name, tuple(columns))

    def parse_drop_table():
        consume(TokenType.KEYWORD)  # DROP
        consume(TokenType.KEYWORD)  # TABLE
        table_name = consume(TokenType.IDENTIFIER).value
        return DropTableStmt(table_name)

    def parse_insert():
        consume(TokenType.KEYWORD)  # INSERT
        consume(TokenType.KEYWORD)  # INTO
        table_name = consume(TokenType.IDENTIFIER).value
        columns = None
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "(":
            consume(TokenType.OPERATOR)  # (
            columns = []
            while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
                columns.append(consume(TokenType.IDENTIFIER).value)
                if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                    consume(TokenType.OPERATOR)  # ,
            consume(TokenType.OPERATOR)  # )
        consume(TokenType.KEYWORD)  # VALUES
        consume(TokenType.OPERATOR)  # (
        values = []
        while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
            token = consume(tokens[0].type)
            if token.type == TokenType.INTEGER:
                values.append(int(token.value))
            elif token.type == TokenType.STRING:
                values.append(token.value)
            elif token.type == TokenType.KEYWORD and token.value == "TRUE":
                values.append(True)
            elif token.type == TokenType.KEYWORD and token.value == "FALSE":
                values.append(False)
            elif token.type == TokenType.KEYWORD and token.value == "NULL":
                values.append(None)
            else:
                raise SQLSyntaxError(f"Unexpected token in VALUES: {token}")
            if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                consume(TokenType.OPERATOR)  # ,
        consume(TokenType.OPERATOR)  # )
        return InsertStmt(table_name, tuple(columns) if columns else None, tuple(values))

    def parse_select():
        consume(TokenType.KEYWORD)  # SELECT
        columns = None
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "*":
            consume(TokenType.OPERATOR)  # *
        else:
            columns = []
            while tokens[0].type != TokenType.KEYWORD or tokens[0].value != "FROM":
                columns.append(consume(TokenType.IDENTIFIER).value)
                if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                    consume(TokenType.OPERATOR)  # ,
        consume(TokenType.KEYWORD)  # FROM
        table_name = consume(TokenType.IDENTIFIER).value
        where_expr = None
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
            consume(TokenType.KEYWORD)  # WHERE
            where_expr = parse_expression(tokens)
        return SelectStmt(table_name, tuple(columns) if columns else None, where_expr)

    def parse_delete():
        consume(TokenType.KEYWORD)  # DELETE
        consume(TokenType.KEYWORD)  # FROM
        table_name = consume(TokenType.IDENTIFIER).value
        where_expr = None
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
            consume(TokenType.KEYWORD)  # WHERE
            where_expr = parse_expression(tokens)
        return DeleteStmt(table_name, where_expr)

    if not tokens:
        raise SQLSyntaxError("Empty input")
    first_token = tokens[0]
    if first_token.type == TokenType.KEYWORD:
        if first_token.value == "CREATE":
            stmt = parse_create_table()
        elif first_token.value == "DROP":
            stmt = parse_drop_table()
        elif first_token.value == "INSERT":
            stmt = parse_insert()
        elif first_token.value == "SELECT":
            stmt = parse_select()
        elif first_token.value == "DELETE":
            stmt = parse_delete()
        else:
            raise SQLSyntaxError(f"Unknown keyword: {first_token.value}")
    else:
        raise SQLSyntaxError(f"Unexpected token: {first_token}")

    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
        consume(TokenType.OPERATOR)  # ;

    consume(TokenType.EOF)  # EOF

    return stmt

def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    statements = []
    while tokens and tokens[0].type != TokenType.EOF:
        try:
            stmt = parse(tokens)
        except SQLSyntaxError as e:
            raise SQLSyntaxError(f"Error in script: {e}")
        if isinstance(stmt, Statement):
            statements.append(stmt)
        if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
            tokens.pop(0)  # consume ;
    consume(TokenType.EOF)  # ensure EOF is the only token left
    return statements

def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    def consume(token_type: TokenType):
        if tokens and tokens[0].type == token_type:
            return tokens.pop(0)
        raise SQLSyntaxError(f"Expected {token_type.value}")

    def parse_primary() -> Expr:
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "(":
            consume(TokenType.OPERATOR)  # (
            expr = parse_or_expr()
            consume(TokenType.OPERATOR)  # )
            return expr
        elif tokens[0].type == TokenType.IDENTIFIER:
            return ColumnRef(consume(TokenType.IDENTIFIER).value)
        elif tokens[0].type == TokenType.INTEGER:
            return Literal(int(consume(TokenType.INTEGER).value))
        elif tokens[0].type == TokenType.STRING:
            return Literal(consume(TokenType.STRING).value)
        elif tokens[0].type == TokenType.KEYWORD:
            if tokens[0].value == "TRUE":
                return Literal(True)
            elif tokens[0].value == "FALSE":
                return Literal(False)
            elif tokens[0].value == "NULL":
                return Literal(None)
            else:
                raise SQLSyntaxError(f"Unexpected keyword: {tokens[0].value}")
        else:
            raise SQLSyntaxError(f"Unexpected token: {tokens[0]}")

    def parse_predicate() -> Expr:
        expr = parse_primary()
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "IS":
            consume(TokenType.KEYWORD)  # IS
            if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
                consume(TokenType.KEYWORD)  # NOT
                consume(TokenType.KEYWORD)  # NULL
                return IsNull(expr, True)
            elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NULL":
                consume(TokenType.KEYWORD)  # NULL
                return IsNull(expr, False)
            else:
                raise SQLSyntaxError(f"Unexpected token after IS: {tokens[0]}")
        elif tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value in COMPARISON_OPS:
            op = consume(TokenType.OPERATOR).value
            right = parse_primary()
            return Comparison(op, expr, right)
        return expr

    def parse_not_expr() -> Expr:
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            consume(TokenType.KEYWORD)  # NOT
            return Not(parse_not_expr())
        return parse_predicate()

    def parse_and_expr() -> Expr:
        expr = parse_not_expr()
        while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "AND":
            consume(TokenType.KEYWORD)  # AND
            right = parse_not_expr()
            expr = And(expr, right)
        return expr

    def parse_or_expr() -> Expr:
        expr = parse_and_expr()
        while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "OR":
            consume(TokenType.KEYWORD)  # OR
            right = parse_and_expr()
            expr = Or(expr, right)
        return expr

    if not tokens:
        raise SQLSyntaxError("Empty expression")
    expr = parse_or_expr()
    consume(TokenType.EOF)  # ensure EOF is the only token left
    return expr

